"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["38797"],{15424(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.fonte_valores_obrigatoria","status":422,"titulo":"Fato categ\xf3rico precisa declarar a fonte dos seus valores"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.fonte_valores_obrigatoria","requisitos":["UNI-REQ-0143","UNI-REQ-0159"],"oQueAconteceu":["Um fato categ\xf3rico chegou sem a fonte dos valores, que indica de onde v\xeam suas op\xe7\xf5es.","A recusa aparece em `errors`, no campo `fonteValores`. Nada \xe9 gravado.","Um c\xf3digo desconhecido recebe [a recusa pr\xf3pria](/erros/uniplus.configuracao.fato_candidato.fonte_valores_invalida)."],"comoResolver":["Informe uma destas fontes, escrita exatamente assim, em mai\xfasculas: `CATALOGO`, `OPCOES_DO_PROCESSO`, `MODALIDADE`, `MUNICIPIOS_DO_FADA`, `UNIDADES_FEDERATIVAS`, `MUNICIPIOS`, `TIPOS_DE_DEFICIENCIA` ou `MUNICIPIOS_PROVA_PRESENCIAL`. Com `CATALOGO`, as op\xe7\xf5es s\xe3o cadastradas no pr\xf3prio fato (`POST /api/configuracao/admin/fatos-candidato/{id}/valores`); nas demais, v\xeam do processo ou de outro cadastro, e o fato n\xe3o guarda valores. O fato derivado por regra categ\xf3rico usa a fonte `CATALOGO`, inferida, e o resumo de grupo herda a do fato de membro."],"ondeAparece":["Cadastro de um fato declarado do cat\xe1logo","Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);